 using System.ComponentModel;
 using System.Text;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptForTopic();

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 // --- Provider + abstraction layer ---------------------------------------------------
 var openAiClient = new OpenAIClient(apiKey);
 IChatClient chatClient = openAiClient.GetChatClient("gpt-4o-mini-2024-07-18").AsIChatClient();

 // --- Tools --------------------------------------------------------------------------
 var notebook = new Notebook();
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         (string query) => WebSearchTool.SearchAsync(query),
         nameof(WebSearchTool.SearchAsync),
         "Searches the web for the given query and returns a list of result snippets."),
     AIFunctionFactory.Create(
         ([Description("Concise title for the note")] string title,
          [Description("Body text to save")] string content) =>
         {
             notebook.Add(title, content);
             return $"Note saved: {title}";
         },
         "SaveNote",
         "Saves a research note with a title and body for later use in the summary."),
     AIFunctionFactory.Create(
         () => notebook.GetAll(),
         "GetNotes",
         "Returns all previously saved research notes."),
 };

 // --- Agent --------------------------------------------------------------------------
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research assistant. Given a topic you must:
         1. Search the web 2-3 times with varied queries to gather diverse information.
         2. Save the most important findings as notes using the SaveNote tool.
         3. After gathering enough information, retrieve your notes and produce a
            well-structured summary with key facts, different perspectives, and sources.
         Be thorough but concise. Always finish with a final written summary.
         """,
     name: "ResearchAgent",
     description: "Researches a topic using web search and note-taking tools",
     tools: tools);

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 // --- Run ----------------------------------------------------------------------------
 var response = await agent.RunAsync(topic, options: runOptions);

 Console.WriteLine("═══════════════════════════════════════════════════════════════");
 Console.WriteLine("  RESEARCH SUMMARY");
 Console.WriteLine("═══════════════════════════════════════════════════════════════");
 Console.WriteLine(response.Text);
